"""Read-only post-run integrity audit; retain generated bytes without restoring/deleting fixtures."""
import argparse
import hashlib
import json
from pathlib import Path
import subprocess
import zipfile


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def inventory(root):
    names = subprocess.check_output(['git', '-C', str(root), 'ls-files', '-z', '--cached', '--others', '--exclude-standard']).decode('utf-8').split('\0')
    return {name: dict(bytes=(root / name).stat().st_size, sha256=digest(root / name))
            for name in names if name and (root / name).is_file()}


def difference(before, after):
    return dict(added=sorted(after.keys() - before.keys()), removed=sorted(before.keys() - after.keys()),
                changed=sorted(name for name in before.keys() & after.keys() if before[name] != after[name]))


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--packet', type=Path, required=True)
    parser.add_argument('--original-corpus', type=Path, required=True)
    args = parser.parse_args()
    packet, original = args.packet.resolve(), args.original_corpus.resolve()
    receipt = json.loads((packet / 'RUN.json').read_text(encoding='utf-8'))
    if receipt['status'] in {'Prepared', 'Running'}:
        raise ValueError('Refusing a final integrity audit while the attempt is active')
    original_before = json.loads((packet / 'ORIGINAL-CORPUS-BEFORE.json').read_text(encoding='utf-8'))
    original_after = inventory(original)
    original_diff = difference(original_before, original_after)
    print('Original corpus compared:', len(original_after), 'files', flush=True)
    corpus = packet / 'corpus'
    before = json.loads((packet / 'CORPUS-BEFORE.json').read_text(encoding='utf-8'))
    after = inventory(corpus)
    (packet / 'CORPUS-AFTER.json').write_text(json.dumps(after, indent=2) + '\n', encoding='utf-8')
    changes = difference(before, after)
    manifest = json.loads((packet / 'RUNTIME-HASHES.json').read_text(encoding='utf-8'))
    runtime_after = {p.relative_to(packet / 'runtime').as_posix(): digest(p)
                     for p in (packet / 'runtime').rglob('*') if p.is_file()}
    runtime_equal = runtime_after == manifest
    with zipfile.ZipFile(packet / 'GENERATED-OUTPUTS.zip', 'w', compression=zipfile.ZIP_DEFLATED) as archive:
        for name in changes['added'] + changes['changed']:
            path = (corpus / name).resolve()
            if not path.is_relative_to(corpus):
                raise ValueError('Generated path escapes the disposable corpus: ' + name)
            archive.write(path, name)
    result = dict(originalCorpusUnchanged=not any(original_diff.values()), originalCorpusFiles=len(original_after),
        originalCorpusDifferences=original_diff, cleanAtStartCorpusFiles=len(before),
        runtimeLayoutUnchanged=runtime_equal, disposableCorpusDifferences=changes,
        generatedOutputsSha256=digest(packet / 'GENERATED-OUTPUTS.zip'),
        testSetDefinitions='Separately checked against every pre-run SHA-256 by report.py',
        policy='All generated/changed bytes retained; neither original nor disposable corpus restored or cleaned')
    (packet / 'AUDIT.json').write_text(json.dumps(result, indent=2) + '\n', encoding='utf-8')
    print(json.dumps({k: v for k, v in result.items() if k != 'disposableCorpusDifferences'}, indent=2))
    print('Disposable corpus changes:', {k: len(v) for k, v in changes.items()})
    return 0 if result['originalCorpusUnchanged'] and runtime_equal else 1


if __name__ == '__main__':
    raise SystemExit(main())
